INSERT INTO stacks (id, market_id, title, stack_type, tags, duration_minutes, published_at, metadata, authored_lesson) VALUES
($ml$b4618f26-6fec-5b0d-9967-d048815168f3$ml$::uuid, $ml$ai$ml$, $ml$What the letters in GPT mean$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-31$ml$, $ml$month-2$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "ai-d31-career", "title": "What the letters in GPT mean", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Read first, specialize later.", "eyebrow": "Day 31 · The model", "headline": "In June 2018, OpenAI's first GPT trained for one month on 8 GPUs.", "fullText": "OpenAI trained a Transformer on a few thousand books, about 5GB of text, to predict the next word. Then it fine-tuned that same model on much smaller labeled datasets, one for each task. The costly first step only had to be done once. The result set new records on a range of language tasks.", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "microInsight", "id": "generative", "eyebrow": "G is for generative", "text": "Generative means the model writes. It picks the most likely next word, then the next.", "highlight": "GPT-2 had one objective: predict the next word, given all the words before it.", "keyTerms": [{"term": "Token", "definition": "A small unit of text, such as a word or part of a word, that a model reads and writes."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"kind": "microInsight", "id": "pretrained", "eyebrow": "P is for pre-trained", "text": "Pre-trained means it first learns from raw text with no labels.", "highlight": "The same model is then fine-tuned on much smaller labeled datasets.", "keyTerms": [{"term": "Fine-tuning", "definition": "Extra training of a pre-trained model on a small dataset for one task."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "info", "id": "transformer", "eyebrow": "T is for Transformer", "title": "GPT keeps half of the 2017 design", "body": "The 2017 Transformer had an encoder and a decoder, six layers each. GPT trains the decoder alone to predict the next word.", "bullets": ["The decoder's mask lets each prediction see only the words before it."], "sources": [{"url": "https://arxiv.org/html/1706.03762v7", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each fact to the letter it explains.", "buckets": ["Generative", "Pre-trained", "Transformer"], "items": [{"text": "Writes text one word at a time", "bucket": 0}, {"text": "Picks the likeliest next word", "bucket": 0}, {"text": "Learns from unlabeled text first", "bucket": 1}, {"text": "Trains once, then gets fine-tuned", "bucket": 1}, {"text": "Uses the decoder from 2017", "bucket": 2}], "explanation": "Generative is what it does, pre-trained is how it learns, and Transformer is the design underneath."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What single objective was GPT-2 trained on?", "options": ["Answer questions written by humans", "Predict the next word from the ones before", "Translate between English and French"], "correctIndex": 1, "explanation": "OpenAI trained GPT-2 to predict the next word, given all the previous words. Everything else came from that."}, {"kind": "numberSense", "id": "ns-gpus", "prompt": "OpenAI's first GPT pre-trained for one month on how many GPUs?", "min": 0, "max": 40, "value": 8, "unit": "GPUs", "explanation": "Eight GPUs for one month. OpenAI noted this costly step only had to be done once."}, {"id": "lens-career", "kind": "info", "title": "Spell out the acronym", "body": "Generative, pre-trained, Transformer. Explaining each word in one line shows you know how these models work.", "eyebrow": "For your interview", "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}]}, {"id": "rule", "kind": "microInsight", "text": "A GPT is a Transformer decoder pre-trained to predict the next word.", "eyebrow": "The rule", "sources": [{"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "GPT stands for generative pre-trained Transformer. It is the decoder half of the 2017 Transformer, pre-trained once on raw text to predict the next word, then fine-tuned for each task.", "sectionKey": "players"}]}$ml$::jsonb),
($ml$785fb71a-d9d0-5632-82a7-883ddfb08771$ml$::uuid, $ml$ai$ml$, $ml$What the letters in GPT mean$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-31$ml$, $ml$month-2$ml$, $ml$handwritten-v1$ml$, $ml$goal:invest$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "ai-d31-invest", "title": "What the letters in GPT mean", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Read first, specialize later.", "eyebrow": "Day 31 · The model", "headline": "In June 2018, OpenAI's first GPT trained for one month on 8 GPUs.", "fullText": "OpenAI trained a Transformer on a few thousand books, about 5GB of text, to predict the next word. Then it fine-tuned that same model on much smaller labeled datasets, one for each task. The costly first step only had to be done once. The result set new records on a range of language tasks.", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "microInsight", "id": "generative", "eyebrow": "G is for generative", "text": "Generative means the model writes. It picks the most likely next word, then the next.", "highlight": "GPT-2 had one objective: predict the next word, given all the words before it.", "keyTerms": [{"term": "Token", "definition": "A small unit of text, such as a word or part of a word, that a model reads and writes."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"kind": "microInsight", "id": "pretrained", "eyebrow": "P is for pre-trained", "text": "Pre-trained means it first learns from raw text with no labels.", "highlight": "The same model is then fine-tuned on much smaller labeled datasets.", "keyTerms": [{"term": "Fine-tuning", "definition": "Extra training of a pre-trained model on a small dataset for one task."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "info", "id": "transformer", "eyebrow": "T is for Transformer", "title": "GPT keeps half of the 2017 design", "body": "The 2017 Transformer had an encoder and a decoder, six layers each. GPT trains the decoder alone to predict the next word.", "bullets": ["The decoder's mask lets each prediction see only the words before it."], "sources": [{"url": "https://arxiv.org/html/1706.03762v7", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each fact to the letter it explains.", "buckets": ["Generative", "Pre-trained", "Transformer"], "items": [{"text": "Writes text one word at a time", "bucket": 0}, {"text": "Picks the likeliest next word", "bucket": 0}, {"text": "Learns from unlabeled text first", "bucket": 1}, {"text": "Trains once, then gets fine-tuned", "bucket": 1}, {"text": "Uses the decoder from 2017", "bucket": 2}], "explanation": "Generative is what it does, pre-trained is how it learns, and Transformer is the design underneath."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What single objective was GPT-2 trained on?", "options": ["Answer questions written by humans", "Predict the next word from the ones before", "Translate between English and French"], "correctIndex": 1, "explanation": "OpenAI trained GPT-2 to predict the next word, given all the previous words. Everything else came from that."}, {"kind": "numberSense", "id": "ns-gpus", "prompt": "OpenAI's first GPT pre-trained for one month on how many GPUs?", "min": 0, "max": 40, "value": 8, "unit": "GPUs", "explanation": "Eight GPUs for one month. OpenAI noted this costly step only had to be done once."}, {"id": "lens-invest", "kind": "info", "title": "Pre-training is the fixed cost", "body": "GPT splits training into one costly pre-training step and cheap fine-tunes. That split shapes who can afford to build models.", "eyebrow": "For investors", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"id": "rule", "kind": "microInsight", "text": "A GPT is a Transformer decoder pre-trained to predict the next word.", "eyebrow": "The rule", "sources": [{"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "GPT stands for generative pre-trained Transformer. It is the decoder half of the 2017 Transformer, pre-trained once on raw text to predict the next word, then fine-tuned for each task.", "sectionKey": "watchlist"}]}$ml$::jsonb),
($ml$3b0042fd-b31c-5a07-93f0-3388f4542ee5$ml$::uuid, $ml$ai$ml$, $ml$What the letters in GPT mean$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-31$ml$, $ml$month-2$ml$, $ml$handwritten-v1$ml$, $ml$goal:build_startup$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "ai-d31-build_startup", "title": "What the letters in GPT mean", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Read first, specialize later.", "eyebrow": "Day 31 · The model", "headline": "In June 2018, OpenAI's first GPT trained for one month on 8 GPUs.", "fullText": "OpenAI trained a Transformer on a few thousand books, about 5GB of text, to predict the next word. Then it fine-tuned that same model on much smaller labeled datasets, one for each task. The costly first step only had to be done once. The result set new records on a range of language tasks.", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "microInsight", "id": "generative", "eyebrow": "G is for generative", "text": "Generative means the model writes. It picks the most likely next word, then the next.", "highlight": "GPT-2 had one objective: predict the next word, given all the words before it.", "keyTerms": [{"term": "Token", "definition": "A small unit of text, such as a word or part of a word, that a model reads and writes."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"kind": "microInsight", "id": "pretrained", "eyebrow": "P is for pre-trained", "text": "Pre-trained means it first learns from raw text with no labels.", "highlight": "The same model is then fine-tuned on much smaller labeled datasets.", "keyTerms": [{"term": "Fine-tuning", "definition": "Extra training of a pre-trained model on a small dataset for one task."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "info", "id": "transformer", "eyebrow": "T is for Transformer", "title": "GPT keeps half of the 2017 design", "body": "The 2017 Transformer had an encoder and a decoder, six layers each. GPT trains the decoder alone to predict the next word.", "bullets": ["The decoder's mask lets each prediction see only the words before it."], "sources": [{"url": "https://arxiv.org/html/1706.03762v7", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each fact to the letter it explains.", "buckets": ["Generative", "Pre-trained", "Transformer"], "items": [{"text": "Writes text one word at a time", "bucket": 0}, {"text": "Picks the likeliest next word", "bucket": 0}, {"text": "Learns from unlabeled text first", "bucket": 1}, {"text": "Trains once, then gets fine-tuned", "bucket": 1}, {"text": "Uses the decoder from 2017", "bucket": 2}], "explanation": "Generative is what it does, pre-trained is how it learns, and Transformer is the design underneath."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What single objective was GPT-2 trained on?", "options": ["Answer questions written by humans", "Predict the next word from the ones before", "Translate between English and French"], "correctIndex": 1, "explanation": "OpenAI trained GPT-2 to predict the next word, given all the previous words. Everything else came from that."}, {"kind": "numberSense", "id": "ns-gpus", "prompt": "OpenAI's first GPT pre-trained for one month on how many GPUs?", "min": 0, "max": 40, "value": 8, "unit": "GPUs", "explanation": "Eight GPUs for one month. OpenAI noted this costly step only had to be done once."}, {"id": "lens-build_startup", "kind": "info", "title": "Fine-tune, do not start over", "body": "Since 2018, the pattern has been to pre-train once and fine-tune for each task. Most startups build at the fine-tune end.", "eyebrow": "For founders", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"id": "rule", "kind": "microInsight", "text": "A GPT is a Transformer decoder pre-trained to predict the next word.", "eyebrow": "The rule", "sources": [{"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "GPT stands for generative pre-trained Transformer. It is the decoder half of the 2017 Transformer, pre-trained once on raw text to predict the next word, then fine-tuned for each task.", "sectionKey": "money"}]}$ml$::jsonb),
($ml$e4301e6e-444f-5df9-ba9b-d252c3d47b0b$ml$::uuid, $ml$ai$ml$, $ml$What the letters in GPT mean$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-31$ml$, $ml$month-2$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "ai-d31-curiosity", "title": "What the letters in GPT mean", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Read first, specialize later.", "eyebrow": "Day 31 · The model", "headline": "In June 2018, OpenAI's first GPT trained for one month on 8 GPUs.", "fullText": "OpenAI trained a Transformer on a few thousand books, about 5GB of text, to predict the next word. Then it fine-tuned that same model on much smaller labeled datasets, one for each task. The costly first step only had to be done once. The result set new records on a range of language tasks.", "sources": [{"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "microInsight", "id": "generative", "eyebrow": "G is for generative", "text": "Generative means the model writes. It picks the most likely next word, then the next.", "highlight": "GPT-2 had one objective: predict the next word, given all the words before it.", "keyTerms": [{"term": "Token", "definition": "A small unit of text, such as a word or part of a word, that a model reads and writes."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"kind": "microInsight", "id": "pretrained", "eyebrow": "P is for pre-trained", "text": "Pre-trained means it first learns from raw text with no labels.", "highlight": "The same model is then fine-tuned on much smaller labeled datasets.", "keyTerms": [{"term": "Fine-tuning", "definition": "Extra training of a pre-trained model on a small dataset for one task."}], "sources": [{"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}, {"url": "https://openai.com/index/language-unsupervised/", "label": "OpenAI, Improving language understanding with unsupervised learning, Jun 2018"}]}, {"kind": "info", "id": "transformer", "eyebrow": "T is for Transformer", "title": "GPT keeps half of the 2017 design", "body": "The 2017 Transformer had an encoder and a decoder, six layers each. GPT trains the decoder alone to predict the next word.", "bullets": ["The decoder's mask lets each prediction see only the words before it."], "sources": [{"url": "https://arxiv.org/html/1706.03762v7", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each fact to the letter it explains.", "buckets": ["Generative", "Pre-trained", "Transformer"], "items": [{"text": "Writes text one word at a time", "bucket": 0}, {"text": "Picks the likeliest next word", "bucket": 0}, {"text": "Learns from unlabeled text first", "bucket": 1}, {"text": "Trains once, then gets fine-tuned", "bucket": 1}, {"text": "Uses the decoder from 2017", "bucket": 2}], "explanation": "Generative is what it does, pre-trained is how it learns, and Transformer is the design underneath."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What single objective was GPT-2 trained on?", "options": ["Answer questions written by humans", "Predict the next word from the ones before", "Translate between English and French"], "correctIndex": 1, "explanation": "OpenAI trained GPT-2 to predict the next word, given all the previous words. Everything else came from that."}, {"kind": "numberSense", "id": "ns-gpus", "prompt": "OpenAI's first GPT pre-trained for one month on how many GPUs?", "min": 0, "max": 40, "value": 8, "unit": "GPUs", "explanation": "Eight GPUs for one month. OpenAI noted this costly step only had to be done once."}, {"id": "lens-curiosity", "kind": "info", "title": "Guess the next word, at scale", "body": "A GPT learns by guessing the next word over and over. Writing, answering and summarizing all grow from that one skill.", "eyebrow": "Why it matters", "sources": [{"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}, {"url": "https://www.ibm.com/think/topics/gpt", "label": "IBM, What is GPT (generative pretrained transformer)?"}]}, {"id": "rule", "kind": "microInsight", "text": "A GPT is a Transformer decoder pre-trained to predict the next word.", "eyebrow": "The rule", "sources": [{"url": "https://huggingface.co/docs/transformers/model_doc/openai-gpt", "label": "Hugging Face Transformers docs, OpenAI GPT"}, {"url": "https://openai.com/index/better-language-models/", "label": "OpenAI, Better language models and their implications, Feb 2019"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "GPT stands for generative pre-trained Transformer. It is the decoder half of the 2017 Transformer, pre-trained once on raw text to predict the next word, then fine-tuned for each task.", "sectionKey": "basics"}]}$ml$::jsonb),
($ml$9366c9ae-6b53-570f-9973-b884c3e8c059$ml$::uuid, $ml$ai$ml$, $ml$Predict the loss, then pay$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-32$ml$, $ml$month-2$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "ai-d32-career", "title": "Predict the loss, then pay", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Small runs price the big bet.", "eyebrow": "Day 32 · The money", "headline": "OpenAI predicted GPT-4's final loss from models trained with up to 10,000 times less compute.", "fullText": "The GPT-4 technical report says OpenAI trained much smaller models the same way and extrapolated from them. That predicted GPT-4's final loss, a measure of how wrong its next-word guesses are. It also predicted a coding pass rate from models with at most 1,000 times less compute.", "sources": [{"url": "https://arxiv.org/html/2303.08774v6", "label": "OpenAI, GPT-4 Technical Report, 2023"}]}, {"kind": "microInsight", "id": "law", "eyebrow": "The curve", "text": "A scaling law is a curve. Loss falls as a power law as you add parameters, data or compute.", "highlight": "In 2020, OpenAI researchers saw such trends hold over more than seven orders of magnitude.", "keyTerms": [{"term": "Loss", "definition": "A score for how wrong a model's next-word guesses are, where lower is better."}], "sources": [{"url": "https://arxiv.org/pdf/2001.08361", "label": "Kaplan et al., Scaling Laws for Neural Language Models, 2020"}]}, {"kind": "microInsight", "id": "recipe", "eyebrow": "The 2020 recipe", "text": "The 2020 paper said to spend extra compute mostly on a bigger model.", "highlight": "For each 10x more compute: about 5x more parameters, only 2x more data.", "sources": [{"url": "https://arxiv.org/pdf/2001.08361", "label": "Kaplan et al., Scaling Laws for Neural Language Models, 2020"}]}, {"kind": "info", "id": "serve", "eyebrow": "The other bill", "title": "Training is paid once, serving every day", "body": "For its 8B Llama 3, the Chinchilla-optimal amount was about 200B tokens. Meta trained far past that, and the model kept improving.", "bullets": ["Meta says smaller models are much more efficient during inference."], "keyTerms": [{"term": "Inference", "definition": "Running a trained model to answer requests, which costs compute every time."}], "sources": [{"url": "https://ai.meta.com/blog/meta-llama-3/", "label": "Meta, Introducing Meta Llama 3, Apr 2024"}]}, {"kind": "numberSense", "id": "ns-less", "prompt": "GPT-4's final loss was predicted from models with up to how many times less compute, in thousands?", "min": 0, "max": 25, "value": 10, "unit": "K", "explanation": "Up to 10,000 times less compute. A cheap curve told OpenAI roughly where the expensive run would land."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did Meta train its small Llama 3 far past the compute-optimal amount of data?", "options": ["Small models are cheaper to run for users", "The law requires a minimum amount of data", "Extra data makes training itself cheaper"], "correctIndex": 0, "explanation": "Meta says smaller models are much more efficient during inference. Paying more once can save on every answer after."}, {"kind": "theCall", "id": "call", "situation": "Your lab has budget for one very large training run. The board wants to know what it will get.", "prompt": "What do you do first?", "options": ["Start the big run and see what comes out", "Copy the size of the largest rival model", "Train small models and fit a scaling curve"], "consequences": ["You learn the result only after the money is spent.", "A rival chose its size for its own budget and data.", "OpenAI predicted GPT-4 this way, from far smaller runs."], "correctIndex": 2, "explanation": "Scaling laws turn a gamble into a forecast. Small runs show where a big one should land."}, {"id": "lens-career", "kind": "info", "title": "Explain why labs can forecast", "body": "Labs predict big runs from small ones. GPT-4's loss was predicted from runs with up to 10,000 times less compute.", "eyebrow": "For your interview", "sources": [{"url": "https://arxiv.org/html/2303.08774v6", "label": "OpenAI, GPT-4 Technical Report, 2023"}]}, {"id": "rule", "kind": "microInsight", "text": "In AI, scaling laws let labs price a big model before they pay for it.", "eyebrow": "The rule", "sources": [{"url": "https://arxiv.org/html/2303.08774v6", "label": "OpenAI, GPT-4 Technical Report, 2023"}, {"url": "https://arxiv.org/pdf/2001.08361", "label": "Kaplan et al., Scaling Laws for Neural Language Models, 2020"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Loss falls on a predictable curve as compute grows, so OpenAI could predict GPT-4 from runs with up to 10,000 times less compute. Serving costs also matter, which is why Meta trained a small Llama 3 far past the optimal point.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
