-- Hand-written ai lessons, days 31-60 (120 stacks: one per day and learner goal).
-- Tagged handwritten-v1, so Days 1-60 pick them over older generated stacks (mobile/lib/handwritten.ts).
-- Safe to run more than once: stacks upsert on id, and each stack's slides are replaced.
-- Too large for Lovable to paste: the load-handwritten-lessons edge functions write these same rows
-- (scripts/lessons/export_loader.py).
BEGIN;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tags = EXCLUDED.tags, stack_type = EXCLUDED.stack_type,
  authored_lesson = EXCLUDED.authored_lesson, duration_minutes = EXCLUDED.duration_minutes,
  published_at = COALESCE(stacks.published_at, EXCLUDED.published_at);

DELETE FROM slides WHERE stack_id IN ('b4618f26-6fec-5b0d-9967-d048815168f3'::uuid, '785fb71a-d9d0-5632-82a7-883ddfb08771'::uuid, '3b0042fd-b31c-5a07-93f0-3388f4542ee5'::uuid, 'e4301e6e-444f-5df9-ba9b-d252c3d47b0b'::uuid, '9366c9ae-6b53-570f-9973-b884c3e8c059'::uuid, '6d62200e-eb5d-5f6f-97ad-9bf2d74f487b'::uuid, '743d01c4-f63f-5a04-ba5e-02b25f6dd02c'::uuid, '8b6a172d-606f-5b3e-b58d-41ee88bda9b9'::uuid, 'c094d522-6659-578e-9150-985320ed10cf'::uuid, 'bf3cd387-4439-517f-be27-5f1a54b1b3f4'::uuid, '84923999-39ec-558b-8665-7c030589dc1a'::uuid, 'a9112133-4349-5b27-8dd6-a447f31a81e0'::uuid, '5b9eefd5-4986-57e5-af94-7a4d1a755875'::uuid, '466467a9-cc3a-5d2a-8e6f-f8d4acb78f71'::uuid, '3151891c-81dd-5e9f-aebf-9e6b35a3ef31'::uuid, '971bddb7-f64f-5670-b6c4-a841c00ac2f2'::uuid, 'af51a99b-a674-55b4-9eff-1242df73d884'::uuid, '88a1468e-5946-5252-97cc-16eeb0e81211'::uuid, '3cab161e-6a08-5cd6-816b-91bf65cc1efe'::uuid, '9d07f476-6ef6-50e1-a9a7-db12e6dea7dc'::uuid, '925c6b1f-7aaf-584f-94e9-61a5856a935c'::uuid, '8c50aeb4-43d6-5750-b15c-da902969bb68'::uuid, '803ddc6b-e025-5268-b876-60dee0ebc795'::uuid, '25820f30-15f0-527c-9d23-b2ec48e4728b'::uuid, 'b459968b-7fc3-5afc-bdc2-c6f044d3cbdd'::uuid, '36926ff6-ba8a-52a7-8d3d-0ede364f1ded'::uuid, '7952a95d-e6d7-5094-bd21-f5b65094ceff'::uuid, 'ed400697-440a-5911-970d-50896185f4a8'::uuid, '5fcb7761-c29b-5721-b0a9-2d0bd18b7efd'::uuid, 'ba1bfef5-3a2c-5047-a9f5-53597f1c6e06'::uuid, '7221ee87-b610-5277-b698-02830624770b'::uuid, 'a0f635ae-6a94-50fa-86e3-c2571ab32ed2'::uuid, '62ccbcdb-cace-560d-862f-c22232d9c5c3'::uuid, 'a49dcf2a-3ac1-51e7-a02b-57b5e9de49f1'::uuid, '1cf808ab-b190-5241-8bc7-70b2c106f96d'::uuid, '2e367b32-4dc1-545a-9954-8b58f58efe9e'::uuid, '0574b0b0-6c75-535a-a923-3eb7544f00df'::uuid, 'cd906d42-5d89-5867-8c56-0b18eb61d7e9'::uuid, '8de5b25b-bc49-5ef2-97fc-918d8e13d94a'::uuid, 'b50e0de7-a11e-5d19-8dc3-dc7e3c083dbd'::uuid, '8d21286d-c4fd-5bdf-8db1-145b474fb58f'::uuid, '1795675b-4b0f-52c5-81b6-ef350e355291'::uuid, 'aa725000-e464-56f6-b0ce-c68a3